<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= $alumno ? 'Editar' : 'Registrar' ?> alumno</title><style>body{font-family:Arial,sans-serif;background:#f1f5f9;margin:0;padding:30px 15px;color:#1e293b}.box{max-width:620px;margin:auto;background:white;padding:25px;border-radius:10px;box-shadow:0 3px 12px #00000012}label{display:block;margin-top:13px}input{box-sizing:border-box;width:100%;padding:10px;margin-top:5px;border:1px solid #cbd5e1;border-radius:4px}button,a{display:inline-block;margin-top:20px;padding:10px 14px;border:0;border-radius:5px;background:#2563eb;color:white;text-decoration:none;cursor:pointer}.errors{background:#fee2e2;color:#991b1b;padding:10px}.errors p{margin:5px}</style></head><body><main class="box"><h1><?= $alumno ? 'Editar alumno' : 'Registrar alumno' ?></h1>
